def solve(inp, fill=None):
    H,W=len(inp),len(inp[0])
    from collections import Counter
    cnt=Counter(v for row in inp for v in row)
    bg=max(cnt,key=lambda v:cnt[v])
    colors=[v for v in cnt if v!=bg]
    col=max(colors,key=lambda v:cnt[v])
    fill = fill if fill is not None else 6
    S={(i,j) for i in range(H) for j in range(W) if inp[i][j]==col}
    rs=min(i for i,j in S); cs=min(j for i,j in S)
    Tnorm=sorted((i-rs,j-cs) for i,j in S)
    g=[row[:] for row in inp]
    changed=True
    while changed:
        changed=False
        for r in range(rs-3,H-2):
            for c in range(cs-3,W-3):
                pts={(r+dr,c+dc) for dr,dc in Tnorm}
                ok=all(g[i][j]!=bg for i,j in pts)
                if ok:
                    for i,j in pts: g[i][j]=fill; changed=True
    return g
