def f(name):
    I=np.array(G[name+' input'])
    cnt={}
    for r in range(len(I)):
        for c in range(len(I[0])):
            v=I[r][c]
            if v!=0: cnt[v]=cnt.get(v,0)+1
    shpcol=min(cnt,key=lambda k:cnt[k])
    H,W=I.shape
    Sset={(r,c) for r in range(H) for c in range(W) if I[r][c]==shpcol}
    # translation vectors relative to shape top-left (min row, min col)
    mr=min(p[0] for p in Sset); mc=min(p[1] for p in Sset)
    rels=[(r-mr,c-mc) for r,c in Sset]
    out=[row[:] for row in I.tolist()]
    res=[]
    for tr in range(-H,H+1):
        for tc in range(-W,W+1):
            cells={(tr+r,tc+c) for r,c in rels}
            if all(0<=rr<H and 0<=cc<W and I[rr][cc]==0 for rr,cc in cells):
                for dr,dc in rels: out[tr+dr][tc+dc]=shpcol
                res.append((tr,tc))
    return I,out,res
